{"path":"firmware/esp32/src/protocols/pal.h","content":"#pragma once

#include <Arduino.h>
#include <stdint.h>
#include <stdbool.h>

// Protocol types
#define PROTO_CAN     0
#define PROTO_RS485   1
#define PROTO_ETHERCAT 2

// CAN message types
#define CAN_MSG_TYPE_COMMAND  0x01
#define CAN_MSG_TYPE_STATUS   0x02
#define CAN_MSG_TYPE_CONFIG   0x03

// RS485 function codes
#define RS485_FUNC_READ_REG   0x03
#define RS485_FUNC_WRITE_REG  0x06
#define RS485_FUNC_READ_MULT  0x04
#define RS485_FUNC_WRITE_MULT 0x10

// EtherCAT CoE object indices
#define ECAT_OBJ_STATUSWORD   0x6041
#define ECAT_OBJ_CONTROLWORD  0x6040
#define ECAT_OBJ_POSITION     0x6064
#define ECAT_OBJ_VELOCITY     0x606C
#define ECAT_OBJ_TORQUE       0x6077

class PAL {
public:
    static bool init(uint8_t protocol);
    static void deinit();

    static bool sendCommand(uint8_t motorId, uint8_t msgType, const uint8_t* data, uint8_t length);
    static bool receiveStatus(uint8_t& motorId, uint8_t& msgType, uint8_t* data, uint8_t& length);

    static bool canSend(uint32_t id, const uint8_t* data, uint8_t length);
    static bool canReceive(uint32_t& id, uint8_t* data, uint8_t& length);

    static bool rs485Send(uint8_t address, const uint8_t* data, uint8_t length);
    static bool rs485Receive(uint8_t& address, uint8_t* data, uint8_t& length);

    static bool ethercatSend(uint8_t motorId, uint16_t objIndex, const uint8_t* data, uint8_t length);
    static bool ethercatReceive(uint8_t motorId, uint16_t objIndex, uint8_t* data, uint8_t& length);

private:
    static uint8_t _protocol;
    static bool _initialized;
};
